FILES
    dest="$KIT/00_강의_시작.md"
    if [[ ! -e "$dest" && ! -L "$dest" ]]; then
      if ! (set -C; printf '%s' "$COURSE_GUIDE" | base64 -D > "$dest"); then failed=$((failed+1)); fi
